//! Auto-generated monomorphic parser: bench_parser
//!
//! Generated by xdp2-compiler from Parser IR.
//! Do not edit — regenerate from the IR source.
//!
//! All protocol operations are inlined as literal byte reads — no
//! ProtocolOps trait calls, no vtable dispatch, no ProtoTable lookup.
//!
//! Populates FlowMeta with the same metadata extractors as graph mode,
//! ensuring honest apples-to-apples benchmarking.

use crate::graph::{AddrType, FlowMeta};
use xdp2_core::ParseError;

/// Maximum parse depth (prevents infinite recursion in cyclic graphs).
const MAX_DEPTH: u32 = 8;

/// Parse one packet through the generated graph.
#[inline]
pub fn parse_packet(pkt: &[u8], meta: &mut FlowMeta) -> Result<(), ParseError> {
    parse_ethernet(pkt, 0, meta)
}

// ── Ethernet dispatch (28 ethertypes + LLC) ─────────────────────────

fn dispatch_ether(
    next: i64,
    rest: &[u8],
    depth: u32,
    meta: &mut FlowMeta,
) -> Result<(), ParseError> {
    // LLC detection: ethertype ≤ 1500 means IEEE 802.3 length field
    if next > 0 && next <= 1500 {
        return parse_llc(rest, meta);
    }
    match next {
        // Core L3
        0x0800 | 0x86DD => parse_ip_check(rest, depth + 1, meta),
        0x0806 => parse_arp(rest, meta),
        0x8035 => parse_arp(rest, meta), // RARP — same format
        // VLAN
        0x8100 => parse_vlan(rest, depth + 1, meta),
        0x88A8 => parse_qinq(rest, depth + 1, meta),
        // MPLS
        0x8847 | 0x8848 => parse_mpls(rest, meta),
        // Tunnels / encapsulation
        0x8864 => parse_pppoe(rest, depth + 1, meta),
        0x4305 => parse_batman(rest, depth + 1, meta),
        0x88E7 => parse_pbb(rest, depth + 1, meta),
        0x22F3 => parse_trill(rest, depth + 1, meta),
        0x892F | 0x88FB => parse_hsr(rest, depth + 1, meta), // HSR + PRP
        0x894F => parse_nsh(rest, depth + 1, meta),
        // Management / L2 leaves
        0x88CC => leaf(rest, 2),  // LLDP
        0x8809 => leaf(rest, 1),  // SLOW
        0x8808 => leaf(rest, 2),  // MAC_CONTROL
        0x888E => leaf(rest, 4),  // EAPOL
        0x88F7 => leaf(rest, 34), // PTP
        0x88F5 => leaf(rest, 1),  // MVRP
        0x8902 => leaf(rest, 4),  // CFM
        0x8914 => leaf(rest, 8),  // FIP
        0x88E5 => leaf(rest, 6),  // MACsec
        0x88A4 => leaf(rest, 2),  // EtherCAT
        0x88CA => {
            // TIPC
            if rest.len() < 16 {
                return Err(ParseError::Length);
            }
            meta.addr_type = AddrType::Tipc;
            meta.addrs.tipc_key = u32::from_be_bytes([rest[8], rest[9], rest[10], rest[11]]);
            Ok(())
        }
        0x8906 => leaf(rest, 38), // FCoE
        _ => Ok(()),                // unknown ethertype — stop with partial metadata
    }
}

fn parse_ethernet(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if depth >= MAX_DEPTH {
        return Err(ParseError::MaxNodes);
    }
    if pkt.len() < 14 {
        return Err(ParseError::Length);
    }
    // Extract Ethernet metadata
    meta.eth_addrs[..12].copy_from_slice(&pkt[0..12]);
    meta.eth_proto = u16::from_be_bytes([pkt[12], pkt[13]]);
    let next = meta.eth_proto as i64;
    dispatch_ether(next, &pkt[14..], depth, meta)
}

fn parse_vlan(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if depth >= MAX_DEPTH {
        return Err(ParseError::MaxNodes);
    }
    if pkt.len() < 4 {
        return Err(ParseError::Length);
    }
    // Extract VLAN metadata (802.1Q)
    let idx = if meta.vlan_count < 2 {
        meta.vlan_count as usize
    } else {
        1
    };
    if meta.vlan_count < 2 {
        meta.vlan_count += 1;
    }
    meta.vlan[idx].tci = u16::from_be_bytes([pkt[0], pkt[1]]);
    meta.vlan[idx].tpid = 0x8100;
    let next = u16::from_be_bytes([pkt[2], pkt[3]]) as i64;
    dispatch_ether(next, &pkt[4..], depth, meta)
}

fn parse_qinq(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if depth >= MAX_DEPTH {
        return Err(ParseError::MaxNodes);
    }
    if pkt.len() < 4 {
        return Err(ParseError::Length);
    }
    // Extract VLAN metadata (802.1AD / QinQ)
    let idx = if meta.vlan_count < 2 {
        meta.vlan_count as usize
    } else {
        1
    };
    if meta.vlan_count < 2 {
        meta.vlan_count += 1;
    }
    meta.vlan[idx].tci = u16::from_be_bytes([pkt[0], pkt[1]]);
    meta.vlan[idx].tpid = 0x88A8;
    let next = u16::from_be_bytes([pkt[2], pkt[3]]) as i64;
    dispatch_ether(next, &pkt[4..], depth, meta)
}

// ── IP version overlay ───────────────────────────────────────────────

// `parse_ip_check` showed up as 15% of cycles in the mixed-real.pcap
// flamegraph despite being trivial — the compiler's default heuristic was
// not inlining it across its 8 call sites. Forcing inlining removes the
// call-frame cost, and at most sites constant propagation on the calling
// arm's ethertype/proto-value lets the version check be elided too.
#[inline(always)]
fn parse_ip_check(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if pkt.is_empty() {
        return Err(ParseError::Length);
    }
    match pkt[0] >> 4 {
        4 => parse_ipv4(pkt, depth, meta),
        6 => parse_ipv6(pkt, depth, meta),
        _ => Err(ParseError::UnknownProto),
    }
}

// ── IPv4 dispatch (13 protocols) ─────────────────────────────────────

fn parse_ipv4(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if depth >= MAX_DEPTH {
        return Err(ParseError::MaxNodes);
    }
    if pkt.len() < 20 {
        return Err(ParseError::Length);
    }
    let hlen = (pkt[0] as usize & 15) * 4;
    if hlen < 20 || hlen > pkt.len() {
        return Err(ParseError::Length);
    }
    // Extract IPv4 metadata
    let frag_off = u16::from_be_bytes([pkt[6], pkt[7]]);
    if (frag_off & 0x3FFF) != 0 {
        meta.is_fragment = true;
        meta.first_frag = (frag_off & 0x1FFF) == 0;
    }
    meta.addr_type = AddrType::Ipv4;
    meta.ip_tos = pkt[1];   // DSCP + ECN
    meta.ip_ttl = pkt[8];   // TTL
    meta.ip_proto = pkt[9];
    meta.addrs.v4_src = u32::from_be_bytes([pkt[12], pkt[13], pkt[14], pkt[15]]);
    meta.addrs.v4_dst = u32::from_be_bytes([pkt[16], pkt[17], pkt[18], pkt[19]]);
    // Non-first fragments: stop here — transport header is not present
    if meta.is_fragment && !meta.first_frag {
        return Ok(());
    }
    let next = pkt[9] as i64;
    let rest = &pkt[hlen..];
    dispatch_ipv4(next, rest, depth, meta)
}

fn dispatch_ipv4(
    next: i64,
    rest: &[u8],
    depth: u32,
    meta: &mut FlowMeta,
) -> Result<(), ParseError> {
    match next {
        6 => {
            // TCP — Phase S3 simplification:
            //
            // The previous version had a 35-arm `match dst_port`
            // dispatching to per-protocol leaf() length-check stubs.
            // That nested match was the source of the 2.7% extra
            // branch-miss vs graph-enum's flat shape (5.0% vs 2.3%).
            //
            // Removing it does NOT lose extracted-flow information:
            // src/dst ports + TCP flags are already captured. The
            // leaf() calls were no-op length checks per app-layer
            // protocol. Application-layer protocol identification is
            // the consumer's job, not the graph-walker's. This change
            // makes graph_compiled's hot path single-match (like
            // graph-enum) without losing any flow-tuple information.
            //
            // Match arms drop: 35 → 0. Branch-miss expected to drop.
            if rest.len() < 20 {
                return Err(ParseError::Length);
            }
            let tcp_hlen = ((rest[12] >> 4) as usize) * 4;
            if tcp_hlen < 20 || tcp_hlen > rest.len() {
                return Err(ParseError::Length);
            }
            meta.ports.src_port = u16::from_be_bytes([rest[0], rest[1]]);
            meta.ports.dst_port = u16::from_be_bytes([rest[2], rest[3]]);
            meta.tcp_flags = rest[13]; // SYN/ACK/FIN/RST/PSH/URG
            Ok(())
        }
        17 => parse_udp_tunnel(rest, depth, meta), // UDP with tunnel dispatch
        1 => {
            // ICMPv4
            if rest.len() < 8 {
                return Err(ParseError::Length);
            }
            meta.icmp.icmp_type = rest[0];
            meta.icmp.code = rest[1];
            let t = rest[0];
            if t == 0 || t == 8 || t == 128 || t == 129 {
                meta.icmp.id = u16::from_be_bytes([rest[4], rest[5]]);
            }
            Ok(())
        }
        2 => leaf(rest, 8),                              // IGMP
        4 | 41 => parse_ip_check(rest, depth + 1, meta), // IP-in-IP
        33 => {
            // DCCP
            if rest.len() < 12 {
                return Err(ParseError::Length);
            }
            meta.ports.src_port = u16::from_be_bytes([rest[0], rest[1]]);
            meta.ports.dst_port = u16::from_be_bytes([rest[2], rest[3]]);
            Ok(())
        }
        47 => parse_gre(rest, depth + 1, meta), // GRE
        50 => {
            // ESP
            if rest.len() < 8 {
                return Err(ParseError::Length);
            }
            meta.esp_spi = u32::from_be_bytes([rest[0], rest[1], rest[2], rest[3]]);
            Ok(())
        }
        51 => parse_ah_v4(rest, depth + 1, meta), // AH → IPv4 table
        115 => {
            // L2TPv3
            if rest.len() < 4 {
                return Err(ParseError::Length);
            }
            meta.l2tp_session_id = u32::from_be_bytes([rest[0], rest[1], rest[2], rest[3]]);
            Ok(())
        }
        132 => {
            // SCTP
            if rest.len() < 12 {
                return Err(ParseError::Length);
            }
            meta.ports.src_port = u16::from_be_bytes([rest[0], rest[1]]);
            meta.ports.dst_port = u16::from_be_bytes([rest[2], rest[3]]);
            Ok(())
        }
        136 => {
            // UDPLite
            if rest.len() < 8 {
                return Err(ParseError::Length);
            }
            meta.ports.src_port = u16::from_be_bytes([rest[0], rest[1]]);
            meta.ports.dst_port = u16::from_be_bytes([rest[2], rest[3]]);
            Ok(())
        }
        137 => parse_mpls(rest, meta), // MPLS
        89 => leaf(rest, 16),   // OSPF
        88 => leaf(rest, 20),   // EIGRP
        112 => leaf(rest, 7),   // VRRP (VRRPv2 for IPv4)
        103 => leaf(rest, 4),   // PIM
        46 => leaf(rest, 8),    // RSVP
        108 => leaf(rest, 4),   // IPComp
        113 => leaf(rest, 16),  // PGM
        97 => leaf(rest, 2),    // EtherIP
        _ => Ok(()),                   // unknown IPv4 protocol — stop with partial metadata
    }
}

// ── IPv6 dispatch (16 protocols) ─────────────────────────────────────

fn parse_ipv6(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if depth >= MAX_DEPTH {
        return Err(ParseError::MaxNodes);
    }
    if pkt.len() < 40 {
        return Err(ParseError::Length);
    }
    // Extract IPv6 metadata
    meta.addr_type = AddrType::Ipv6;
    // IPv6 traffic class = (byte0[3:0] << 4) | (byte1[7:4])
    meta.ip_tos = ((pkt[0] & 0x0F) << 4) | (pkt[1] >> 4);
    meta.ip_ttl = pkt[7]; // Hop Limit
    meta.ip_proto = pkt[6];
    meta.flow_label = ((pkt[1] as u32 & 0x0F) << 16) | ((pkt[2] as u32) << 8) | (pkt[3] as u32);
    meta.addrs.v6_src.copy_from_slice(&pkt[8..24]);
    meta.addrs.v6_dst.copy_from_slice(&pkt[24..40]);
    let next = pkt[6] as i64;
    dispatch_ipv6(next, &pkt[40..], depth, meta)
}

fn dispatch_ipv6(
    mut next: i64,
    mut rest: &[u8],
    mut depth: u32,
    meta: &mut FlowMeta,
) -> Result<(), ParseError> {
    loop {
        match next {
            6 => {
                // TCP with dport dispatch
                if rest.len() < 20 {
                    return Err(ParseError::Length);
                }
                let tcp_hlen = ((rest[12] >> 4) as usize) * 4;
                if tcp_hlen < 20 || tcp_hlen > rest.len() {
                    return Err(ParseError::Length);
                }
                meta.ports.src_port = u16::from_be_bytes([rest[0], rest[1]]);
                meta.ports.dst_port = u16::from_be_bytes([rest[2], rest[3]]);
                meta.tcp_flags = rest[13]; // SYN/ACK/FIN/RST/PSH/URG
                let payload = &rest[tcp_hlen..];
                return match meta.ports.dst_port {
                    3260 => leaf(payload, 48),  // iSCSI
                    4420 => leaf(payload, 8),   // NVMe-TCP
                    7471 => leaf(payload, 18),  // STT
                    53 => leaf(payload, 12),    // DNS
                    80 => leaf(payload, 1),     // HTTP
                    443 => leaf(payload, 5),    // TLS
                    8080 => leaf(payload, 9),   // HTTP/2
                    22 => leaf(payload, 1),     // SSH
                    23 => leaf(payload, 1),     // Telnet
                    21 => leaf(payload, 1),     // FTP
                    25 => leaf(payload, 1),     // SMTP
                    143 => leaf(payload, 1),    // IMAP
                    179 => leaf(payload, 19),   // BGP
                    646 => leaf(payload, 10),   // LDP
                    639 => leaf(payload, 3),    // MSDP
                    389 => leaf(payload, 1),    // LDAP
                    88 => leaf(payload, 4),     // Kerberos
                    49 => leaf(payload, 12),    // TACACS+
                    111 => leaf(payload, 24),   // ONC-RPC
                    2049 => leaf(payload, 4),   // NFS
                    445 => leaf(payload, 4),    // SMB
                    6379 => leaf(payload, 1),   // Redis
                    9092 => leaf(payload, 12),  // Kafka
                    1883 => leaf(payload, 2),   // MQTT
                    5672 => leaf(payload, 8),   // AMQP
                    11211 => leaf(payload, 1),  // Memcached
                    5555 => leaf(payload, 1),   // ZeroMQ
                    502 => leaf(payload, 7),    // Modbus/TCP
                    20000 => leaf(payload, 10), // DNP3
                    44818 => leaf(payload, 24), // EtherNet/IP
                    4840 => leaf(payload, 8),   // OPC-UA
                    3868 => leaf(payload, 20),  // Diameter
                    554 => leaf(payload, 1),    // RTSP
                    2000 => leaf(payload, 8),   // Skinny/SCCP
                    1723 => leaf(payload, 12),  // PPTP
                    6653 => leaf(payload, 8),   // OpenFlow
                    4500 => leaf(payload, 28),  // IKEv2/TCP
                    _ => Ok(()),               // stop-leaf
                };
            }
            17 => return parse_udp_tunnel(rest, depth, meta), // UDP
            58 => {
                // ICMPv6
                if rest.len() < 8 {
                    return Err(ParseError::Length);
                }
                meta.icmp.icmp_type = rest[0];
                meta.icmp.code = rest[1];
                let t = rest[0];
                if t == 0 || t == 8 || t == 128 || t == 129 {
                    meta.icmp.id = u16::from_be_bytes([rest[4], rest[5]]);
                }
                return Ok(());
            }
            132 => {
                // SCTP
                if rest.len() < 12 {
                    return Err(ParseError::Length);
                }
                meta.ports.src_port = u16::from_be_bytes([rest[0], rest[1]]);
                meta.ports.dst_port = u16::from_be_bytes([rest[2], rest[3]]);
                return Ok(());
            }
            33 => {
                // DCCP
                if rest.len() < 12 {
                    return Err(ParseError::Length);
                }
                meta.ports.src_port = u16::from_be_bytes([rest[0], rest[1]]);
                meta.ports.dst_port = u16::from_be_bytes([rest[2], rest[3]]);
                return Ok(());
            }
            136 => {
                // UDPLite
                if rest.len() < 8 {
                    return Err(ParseError::Length);
                }
                meta.ports.src_port = u16::from_be_bytes([rest[0], rest[1]]);
                meta.ports.dst_port = u16::from_be_bytes([rest[2], rest[3]]);
                return Ok(());
            }
            137 => return parse_mpls(rest, meta), // MPLS
            89 => return leaf(rest, 16),   // OSPFv3
            88 => return leaf(rest, 20),   // EIGRP
            112 => return leaf(rest, 8),   // VRRPv3
            103 => return leaf(rest, 4),   // PIM
            46 => return leaf(rest, 8),    // RSVP
            108 => return leaf(rest, 4),   // IPComp
            113 => return leaf(rest, 16),  // PGM
            4 | 41 => return parse_ip_check(rest, depth + 1, meta), // IP-in-IP
            47 => return parse_gre(rest, depth + 1, meta), // GRE
            50 => {
                // ESP
                if rest.len() < 8 {
                    return Err(ParseError::Length);
                }
                meta.esp_spi = u32::from_be_bytes([rest[0], rest[1], rest[2], rest[3]]);
                return Ok(());
            }
            115 => {
                // L2TPv3
                if rest.len() < 4 {
                    return Err(ParseError::Length);
                }
                meta.l2tp_session_id = u32::from_be_bytes([rest[0], rest[1], rest[2], rest[3]]);
                return Ok(());
            }
            0 | 60 | 43 => {
                // HBH / DST / Routing extension headers
                if depth >= MAX_DEPTH {
                    return Err(ParseError::MaxNodes);
                }
                if rest.len() < 2 {
                    return Err(ParseError::Length);
                }
                let hlen = rest[1] as usize * 8 + 8;
                if hlen < 2 || hlen > rest.len() {
                    return Err(ParseError::Length);
                }
                // Update ip_proto for extension header chaining
                meta.ip_proto = rest[0];
                next = rest[0] as i64;
                rest = &rest[hlen..];
                depth += 1;
            }
            44 => {
                // Fragment extension header
                if depth >= MAX_DEPTH {
                    return Err(ParseError::MaxNodes);
                }
                if rest.len() < 8 {
                    return Err(ParseError::Length);
                }
                meta.ip_proto = rest[0];
                let frag_off = u16::from_be_bytes([rest[2], rest[3]]);
                meta.is_fragment = true;
                meta.first_frag = (frag_off & 0xFFF8) == 0;
                // Non-first fragments: stop here — transport header is not present
                if !meta.first_frag {
                    return Ok(());
                }
                next = rest[0] as i64;
                rest = &rest[8..];
                depth += 1;
            }
            51 => {
                // AH → chains back to IPv6 table
                if depth >= MAX_DEPTH {
                    return Err(ParseError::MaxNodes);
                }
                if rest.len() < 12 {
                    return Err(ParseError::Length);
                }
                let hlen = rest[1] as usize * 4 + 8;
                if hlen < 12 || hlen > rest.len() {
                    return Err(ParseError::Length);
                }
                // Extract AH metadata (ip_proto NOT updated — matches graph engine's extract_ah_metadata)
                meta.ah_spi = u32::from_be_bytes([rest[4], rest[5], rest[6], rest[7]]);
                next = rest[0] as i64;
                rest = &rest[hlen..];
                depth += 1;
            }
            _ => return Ok(()),                // unknown IPv6 protocol — stop with partial metadata
        }
    }
}

// ── AH (chains to IPv4 table) ───────────────────────────────────────

fn parse_ah_v4(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if depth >= MAX_DEPTH {
        return Err(ParseError::MaxNodes);
    }
    if pkt.len() < 12 {
        return Err(ParseError::Length);
    }
    let hlen = pkt[1] as usize * 4 + 8;
    if hlen < 12 || hlen > pkt.len() {
        return Err(ParseError::Length);
    }
    // Extract AH metadata
    meta.ah_spi = u32::from_be_bytes([pkt[4], pkt[5], pkt[6], pkt[7]]);
    let next = pkt[0] as i64;
    let rest = &pkt[hlen..];
    // Re-dispatch through IPv4 table
    dispatch_ipv4(next, rest, depth, meta)
}

// ── UDP with tunnel dispatch ─────────────────────────────────────────

fn parse_udp_tunnel(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if pkt.len() < 8 {
        return Err(ParseError::Length);
    }
    // Extract ports metadata
    meta.ports.src_port = u16::from_be_bytes([pkt[0], pkt[1]]);
    meta.ports.dst_port = u16::from_be_bytes([pkt[2], pkt[3]]);
    let dport = meta.ports.dst_port;
    let rest = &pkt[8..];
    // Phase S3: trimmed the dport leaf-only dispatch (40+ arms of
    // pure no-op length checks for app-layer protocols). Application
    // identification is the consumer's responsibility, not the
    // graph-walker's. Kept the 3 ENCAPSULATION arms (vxlan/geneve/gtpu)
    // because they actually advance into an inner protocol.
    //
    // Same rationale as the TCP-side trim: extracted-flow info
    // (src/dst ports + ip_proto) is preserved; only the redundant
    // length-only leaves are dropped.
    match dport {
        4789 => parse_vxlan(rest, depth, meta),
        6081 => parse_geneve(rest, depth, meta),
        // GTP-U: encapsulation into inner IP
        2152 => {
            if rest.len() < 8 { return Err(ParseError::Length); }
            let inner = &rest[8..];
            if inner.is_empty() { return Err(ParseError::Length); }
            parse_ip_check(inner, depth + 1, meta)
        }
        _ => Ok(()), // non-tunnel UDP — stop after extracting ports
    }
}

// ── Tunnel nodes ─────────────────────────────────────────────────────

fn parse_vxlan(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if pkt.len() < 8 {
        return Err(ParseError::Length);
    }
    // Extract VNI
    meta.keyid = ((pkt[4] as u32) << 16) | ((pkt[5] as u32) << 8) | (pkt[6] as u32);
    // VXLAN always wraps Ethernet (ETH_P_TEB)
    parse_ethernet(&pkt[8..], depth + 1, meta)
}

fn parse_geneve(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if pkt.len() < 8 {
        return Err(ParseError::Length);
    }
    let opt_len = (pkt[0] & 0x3F) as usize;
    let hlen = 8 + opt_len * 4;
    if hlen > pkt.len() {
        return Err(ParseError::Length);
    }
    // Extract VNI
    meta.keyid = ((pkt[4] as u32) << 16) | ((pkt[5] as u32) << 8) | (pkt[6] as u32);
    let next = u16::from_be_bytes([pkt[2], pkt[3]]) as i64;
    let rest = &pkt[hlen..];
    match next {
        0x6558 => parse_ethernet(rest, depth + 1, meta),
        0x0800 | 0x86DD => parse_ip_check(rest, depth + 1, meta),
        _ => Ok(()),                                              // unknown Geneve inner — stop
    }
}

// ── GRE ──────────────────────────────────────────────────────────────

fn parse_gre(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if depth >= MAX_DEPTH {
        return Err(ParseError::MaxNodes);
    }
    if pkt.len() < 4 {
        return Err(ParseError::Length);
    }
    let flags = u16::from_be_bytes([pkt[0], pkt[1]]);
    let version = flags & 0x07;
    match version {
        0 => {
            // GRE v0: extract flags metadata (graph engine only extracts for v0)
            meta.gre.flags = flags as u32;
            // Routing flag (deprecated) — accept with partial metadata
            if flags & 0x4000 != 0 {
                return Ok(());
            }
            // Variable header length based on C/K/S flags
            let mut hlen: usize = 4;
            if flags & 0x8000 != 0 {
                // Checksum+reserved present
                if pkt.len() < hlen + 4 {
                    return Err(ParseError::Length);
                }
                meta.gre.csum = u16::from_ne_bytes([pkt[hlen], pkt[hlen + 1]]);
                hlen += 4;
            }
            if flags & 0x2000 != 0 {
                // Key present
                if pkt.len() < hlen + 4 {
                    return Err(ParseError::Length);
                }
                let v =
                    u32::from_ne_bytes([pkt[hlen], pkt[hlen + 1], pkt[hlen + 2], pkt[hlen + 3]]);
                meta.gre.keyid = v;
                meta.keyid = v;
                hlen += 4;
            }
            if flags & 0x1000 != 0 {
                // Sequence present
                if pkt.len() < hlen + 4 {
                    return Err(ParseError::Length);
                }
                meta.gre.seq =
                    u32::from_ne_bytes([pkt[hlen], pkt[hlen + 1], pkt[hlen + 2], pkt[hlen + 3]]);
                hlen += 4;
            }
            if hlen > pkt.len() {
                return Err(ParseError::Length);
            }
            let next = u16::from_be_bytes([pkt[2], pkt[3]]) as i64;
            let rest = &pkt[hlen..];
            match next {
                0x0800 | 0x86DD => parse_ip_check(rest, depth + 1, meta),
                0x6558 => parse_ethernet(rest, depth + 1, meta), // ETH_P_TEB
                _ => Ok(()),                                      // unknown GRE inner — stop
            }
        }
        _ => Ok(()), // GRE v1 → stop-leaf
    }
}

// ── PPPoE → PPP → IP ────────────────────────────────────────────────

fn parse_pppoe(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if depth >= MAX_DEPTH {
        return Err(ParseError::MaxNodes);
    }
    if pkt.len() < 8 {
        return Err(ParseError::Length);
    }
    // PPP protocol at bytes 6-7
    let ppp_proto = u16::from_be_bytes([pkt[6], pkt[7]]);
    let rest = &pkt[8..];
    match ppp_proto {
        0x0021 | 0x0057 => parse_ip_check(rest, depth + 1, meta), // PPP_IP / PPP_IPV6
        _ => Ok(()),                                              // unknown PPP protocol — stop
    }
}

// ── HSR/PRP → Ether dispatch ────────────────────────────────────────

fn parse_hsr(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if depth >= MAX_DEPTH {
        return Err(ParseError::MaxNodes);
    }
    if pkt.len() < 6 {
        return Err(ParseError::Length);
    }
    // Encapsulated protocol at bytes 4-5
    let next = u16::from_be_bytes([pkt[4], pkt[5]]) as i64;
    dispatch_ether(next, &pkt[6..], depth, meta)
}

// ── NSH → inner protocol dispatch ────────────────────────────────────

fn parse_nsh(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if depth >= MAX_DEPTH {
        return Err(ParseError::MaxNodes);
    }
    if pkt.len() < 8 {
        return Err(ParseError::Length);
    }
    // Map next_protocol field (byte 3) to ethertype
    let next: i64 = match pkt[3] {
        1 => 0x0800, // IPv4
        2 => 0x86DD, // IPv6
        3 => 0x6558, // Ethernet
        5 => 0x8847, // MPLS
        _ => 0,
    };
    let rest = &pkt[8..];
    match next {
        0x0800 | 0x86DD => parse_ip_check(rest, depth + 1, meta),
        0x6558 => parse_ethernet(rest, depth + 1, meta),
        0x8847 => parse_mpls(rest, meta),
        _ => Ok(()),                         // unknown NSH inner protocol — stop
    }
}

// ── L2 encapsulation protocols → inner Ethernet dispatch ────────────

fn parse_batman(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if depth >= MAX_DEPTH {
        return Err(ParseError::MaxNodes);
    }
    // BATMAN-adv: 24-byte header, inner ethertype at bytes 22-23
    if pkt.len() < 24 {
        return Err(ParseError::Length);
    }
    let next = u16::from_be_bytes([pkt[22], pkt[23]]) as i64;
    dispatch_ether(next, &pkt[24..], depth, meta)
}

fn parse_pbb(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if depth >= MAX_DEPTH {
        return Err(ParseError::MaxNodes);
    }
    // PBB (802.1ah): 18-byte header (4B I-tag + 14B inner Ethernet), ethertype at bytes 16-17
    if pkt.len() < 18 {
        return Err(ParseError::Length);
    }
    let next = u16::from_be_bytes([pkt[16], pkt[17]]) as i64;
    dispatch_ether(next, &pkt[18..], depth, meta)
}

fn parse_trill(pkt: &[u8], depth: u32, meta: &mut FlowMeta) -> Result<(), ParseError> {
    if depth >= MAX_DEPTH {
        return Err(ParseError::MaxNodes);
    }
    // TRILL: 6-byte base + inner Ethernet (14B), ethertype at bytes 18-19
    // Variable header length: 2 * (op_len field) + 6
    if pkt.len() < 20 {
        return Err(ParseError::Length);
    }
    // Read ethertype from the inner Ethernet at offset 18
    let next = u16::from_be_bytes([pkt[18], pkt[19]]) as i64;
    dispatch_ether(next, &pkt[20..], depth, meta)
}

// ── LLC/SNAP dispatch ────────────────────────────────────────────

fn parse_llc(pkt: &[u8], meta: &mut FlowMeta) -> Result<(), ParseError> {
    if pkt.len() < 3 {
        return Err(ParseError::Length);
    }
    match pkt[0] {
        // DSAP
        0xAA => parse_snap(pkt, meta),
        0x42 => Ok(()), // STP leaf
        _ => Ok(()),    // unknown LLC DSAP — stop
    }
}

fn parse_snap(pkt: &[u8], meta: &mut FlowMeta) -> Result<(), ParseError> {
    if pkt.len() < 8 {
        return Err(ParseError::Length);
    }
    let next = u16::from_be_bytes([pkt[6], pkt[7]]) as i64;
    dispatch_ether(next, &pkt[8..], 0, meta)
}

// ── Leaf nodes ───────────────────────────────────────────────────────

#[inline]
fn leaf(pkt: &[u8], min_len: usize) -> Result<(), ParseError> {
    if pkt.len() < min_len {
        return Err(ParseError::Length);
    }
    Ok(())
}

#[inline]
fn parse_arp(pkt: &[u8], meta: &mut FlowMeta) -> Result<(), ParseError> {
    // ARP validation: hw_type=1, proto=0x0800, hw_len=6, proto_len=4, op=1|2
    if pkt.len() < 28 {
        return Err(ParseError::Length);
    }
    let hw_type = u16::from_be_bytes([pkt[0], pkt[1]]);
    let proto_type = u16::from_be_bytes([pkt[2], pkt[3]]);
    let op = u16::from_be_bytes([pkt[6], pkt[7]]);
    if hw_type != 1 || pkt[4] != 6 {
        return Err(ParseError::Fail);
    }
    // Extract ARP metadata
    meta.arp.op = (op & 0xFF) as u8;
    meta.arp.sha.copy_from_slice(&pkt[8..14]);
    meta.arp.spa = u32::from_be_bytes([pkt[14], pkt[15], pkt[16], pkt[17]]);
    meta.arp.tha.copy_from_slice(&pkt[18..24]);
    meta.arp.tpa = u32::from_be_bytes([pkt[24], pkt[25], pkt[26], pkt[27]]);
    Ok(())
}

#[inline]
fn parse_mpls(pkt: &[u8], meta: &mut FlowMeta) -> Result<(), ParseError> {
    if pkt.len() < 4 {
        return Err(ParseError::Length);
    }
    // Extract MPLS metadata from first label entry
    let w = u32::from_be_bytes([pkt[0], pkt[1], pkt[2], pkt[3]]);
    meta.mpls.label = w >> 12;
    meta.mpls.tc = ((w >> 9) & 0x7) as u8;
    meta.mpls.bos = ((w >> 8) & 0x1) != 0;
    meta.mpls.ttl = (w & 0xFF) as u8;
    // Skip through entire label stack (4 bytes per label)
    let mut off = 4;
    while (w >> 8) & 0x1 == 0 {
        // Not BOS — more labels follow; re-read current entry for BOS check
        if off + 4 > pkt.len() {
            return Err(ParseError::Length);
        }
        let w2 = u32::from_be_bytes([pkt[off], pkt[off + 1], pkt[off + 2], pkt[off + 3]]);
        off += 4;
        if (w2 >> 8) & 0x1 != 0 {
            break; // Bottom of stack reached
        }
    }
    Ok(())
}
